<?php
declare(strict_types=1);
function corpus():array{static $d=null;return $d??=json_decode(file_get_contents(__DIR__.'/ledger.json'),true,512,JSON_THROW_ON_ERROR);}
function records():array{return array_column(corpus()['records'],null,'id');}
function specs():array{return [
'escape'=>['title'=>'Escape-assisted population','description'=>'Review 6.0 §15.6, K11–K13: exact selected-mode resonant solution in dimensionless time u=GT.','params'=>['ratio'=>['Escape ratio κ/G',4,0,16,.1],'duration'=>['Duration GT',12,.5,40,.5]],'record'=>'escape-criterion','series'=>['Incident population','Local converted','Escaped population','Total converted'],'x'=>'GT'],
'wall'=>['title'=>'Fixed-gap wall feasibility','description'=>'Review 6.0 §10.3–10.4: necessary endpoint retention bound and constant-drag crossing inequality.','params'=>['loggap'=>['log₁₀ gap fraction',-1,-16,-.05,.05],'ceiling'=>['Ceiling ratio s',1.2,1.001,2,.001]],'record'=>'wall-crossing','series'=>['log₁₀ maximum retained energy'],'x'=>'Ceiling ratio'],
'anchors'=>['title'=>'Geometric anchor sensitivity','description'=>'Review 6.0 §14.8: proposed downward distance shift in units of quoted combined uncertainty.','params'=>['percent'=>['Downward shift (%)',5,0,30,.1]],'record'=>'anchor-lmc','series'=>['LMC','NGC 4258'],'x'=>'Downward shift (%)']];}
function calc(string $id,array $input=[]):array{if(!isset(specs()[$id]))throw new InvalidArgumentException('Unknown workbench.');$s=specs()[$id];$p=[];foreach($input as $k=>$v)if(!isset($s['params'][$k]))throw new InvalidArgumentException('Unknown parameter.');foreach($s['params'] as $k=>$v){$a=array_key_exists($k,$input)?$input[$k]:$v[1];if(!is_numeric($a)||!is_finite((float)$a)||(float)$a<$v[2]||(float)$a>$v[3])throw new InvalidArgumentException('Parameter outside allowed range: '.$k);$p[$k]=(float)$a;}$rows=[];$metrics=[];$add=function($label,$value,$unit='')use(&$metrics){$metrics[]=compact('label','value','unit');};
if($id==='escape'){$q=$p['ratio']/4;$max=$p['duration'];$min=0.;for($i=0;$i<=400;$i++){$u=$max*$i/400;$disc=$q*$q-1;if(abs($disc)<1e-12){$a=(1+$u)*exp(-$u);$y=$u*exp(-$u);}elseif($disc>0){$b=sqrt($disc);$e1=exp(-$u/($q+$b));$e2=exp(-($q+$b)*$u);$a=.5*(($e1+$e2)+$q/$b*($e1-$e2));$y=($e1-$e2)/(2*$b);}else{$b=sqrt(-$disc);$e=exp(-$q*$u);$a=$e*(cos($b*$u)+$q*sin($b*$u)/$b);$y=$e*sin($b*$u)/$b;}$esc=1-$a*$a-$y*$y;$rows[]=[$u,$a*$a,$y*$y,$esc,1-$a*$a];$min=min($min,2*$a*$y);}$last=end($rows);$add('Continuous monotonicity criterion',$p['ratio']>=4?'Satisfied (κ/G ≥ 4)':'Not satisfied (local back-conversion possible)');$add('Final escaped population',$last[3]);$add('Final total converted',$last[4]);$add('Minimum sampled dP/du',$min);$note='Analytic selected-mode control; escaped population is monotone for nonnegative κ, but total conversion is guaranteed monotone only at or above critical damping. No individual-photon speed law is derived.';
}elseif($id==='wall'){$e=10**$p['loggap'];$s0=$p['ceiling'];$y=acosh(1/$e);$low=($s0-1)*sqrt(1-$e*$e)/($e*$e);$upper=($s0-1)*$y/log($s0);$bound=fn($s)=>$e*$s/sqrt(($s-1)*($s+1)+$e*$e);for($i=0;$i<=200;$i++){$s=1+.001+.999*$i/200;$rows[]=[$s,log10($bound($s))];}$add('Maximum retained fraction',$bound($s0));$add('Minimum entry-monotone drag',$low,'normalized');$add('Strict upper drag for crossing',$upper,'normalized');$add('Constant-drag feasibility',$low<$upper?'Interval exists':'No feasible interval');$note='Endpoint bound is necessary, not sufficient. The inequality applies to the static linear-wall fixed-gap model with normalized wall length. No actual cosmic wall is inferred.';
}else{$a=49.59/hypot(.09,.54);$b=7.576/hypot(.082,.076);for($i=0;$i<=150;$i++){$x=$i/5;$rows[]=[$x,$a*$x/100,$b*$x/100];}$add('LMC shift / combined uncertainty',$a*$p['percent']/100);$add('NGC 4258 shift / combined uncertainty',$b*$p['percent']/100);$add('Shifted LMC distance',49.59*(1-$p['percent']/100),'kpc');$add('Shifted NGC 4258 distance',7.576*(1-$p['percent']/100),'Mpc');$note='Illustrative arithmetic assumes unchanged calibration and quadrature combination of quoted statistical and systematic errors. These ratios are not joint likelihood significances or new measurements.';}
return ['schema'=>'beyondspacetime.evidence-result.v1','version'=>'1.4.0','workbench'=>$id,'parameters'=>$p,'metrics'=>$metrics,'rows'=>$rows,'series'=>specs()[$id]['series'],'x'=>specs()[$id]['x'],'limitation'=>$note,'source'=>corpus()['source'],'record'=>specs()[$id]['record']];}
